def solve(inputs: dict) -> float:
    a = inputs['terms']
    # continued fraction numerator via recurrence
    p_minus2 = 0
    p_minus1 = 1
    for ai in a:
        p = ai * p_minus1 + p_minus2
        p_minus2, p_minus1 = p_minus1, p
    return float(p_minus1)

